async function cueCardFlow(page: Page) {
  await page.getByRole("button", { name: /监听提词台/ }).click();
  await page.getByPlaceholder("例如：请介绍一个你做过的项目，以及你具体负责什么？").fill("请介绍一个你做过的 AI 产品项目，以及你具体负责什么？");
